<?php
$q=trim((string)($_GET['q']??''));$loc=trim((string)($_GET['loc']??''));$type=(string)($_GET['type']??'');
$mode=(string)($_GET['mode']??'');$level=(string)($_GET['level']??'');$sort=(string)($_GET['sort']??'newest');
$pg=max(1,(int)($_GET['p']??1));$per=9;
$where=["j.status='approved'","(d.deadline IS NULL OR d.deadline >= CURDATE())"];$args=[];
if ($q!=='') {$where[]='(j.title LIKE ? OR j.company LIKE ? OR j.skills LIKE ? OR j.description LIKE ?)';$term='%'.$q.'%';array_push($args,$term,$term,$term,$term);}
if ($loc!=='') {$where[]='j.location LIKE ?';$args[]='%'.$loc.'%';}
if (in_array($type,['full_time','part_time','internship','contract'],true)) {$where[]='d.job_type=?';$args[]=$type;}
if (in_array($mode,['onsite','hybrid','remote'],true)) {$where[]='d.work_mode=?';$args[]=$mode;}
if (in_array($level,['intern','junior','mid','senior'],true)) {$where[]='d.level=?';$args[]=$level;}
$order=['newest'=>'j.id DESC','oldest'=>'j.id ASC','az'=>'j.title ASC, j.id DESC'];
$sort=array_key_exists($sort,$order)?$sort:'newest';
$filter=implode(' AND ',$where);
$total=sr_count('SELECT COUNT(*) FROM jobs j LEFT JOIN job_details d ON d.job_id=j.id WHERE '.$filter,$args);
$maxPg=max(1,(int)ceil($total/$per));$pg=min($pg,$maxPg);$offset=($pg-1)*$per;
$jobs=sr_all('SELECT j.*,d.job_type,d.work_mode,d.level,d.deadline FROM jobs j LEFT JOIN job_details d ON d.job_id=j.id WHERE '.$filter.' ORDER BY '.$order[$sort].' LIMIT '.(int)$per.' OFFSET '.(int)$offset,$args);
$shown=sr_count("SELECT COUNT(*) FROM jobs WHERE status='approved'");$employers=sr_count('SELECT COUNT(DISTINCT recruiter_id) FROM jobs');
$u=sr_current();$savedIds=[];
if($u&&$u['role']==='candidate')foreach(sr_all('SELECT job_id FROM saved_jobs WHERE user_id=?',[$u['id']]) as $row)$savedIds[(int)$row['job_id']]=true;
$filterCount=(int)($q!=='')+(int)($loc!=='')+(int)($type!=='')+(int)($mode!=='')+(int)($level!=='');
?>
