<div class="browse-layout"><aside class="panel filter-panel"><div class="filter-title"><h3>Bộ lọc tìm kiếm</h3><?php if($filterCount):?><span class="filter-count"><?=$filterCount?></span><?php endif;?></div><form method="get" class="stack-form"><input type="hidden" name="page" value="home"><label>Từ khóa<input name="q" value="<?=h($q)?>" placeholder="Vị trí, công nghệ..."></label><label>Địa điểm<input name="loc" value="<?=h($loc)?>" placeholder="Hà Nội, TP.HCM..."></label><label>Loại công việc<select name="type"><option value="">Tất cả</option><?php foreach(['full_time','part_time','internship','contract'] as $v):?><option value="<?=$v?>" <?=$type===$v?'selected':''?>><?=h(sr_status($v))?></option><?php endforeach;?></select></label><label>Hình thức<select name="mode"><option value="">Tất cả</option><?php foreach(['onsite','hybrid','remote'] as $v):?><option value="<?=$v?>" <?=$mode===$v?'selected':''?>><?=h(sr_status($v))?></option><?php endforeach;?></select></label><label>Cấp bậc<select name="level"><option value="">Tất cả</option><?php foreach(['intern','junior','mid','senior'] as $v):?><option value="<?=$v?>" <?=$level===$v?'selected':''?>><?=h(sr_status($v))?></option><?php endforeach;?></select></label><input type="hidden" name="sort" value="<?=h($sort)?>"><button class="button primary block">Áp dụng bộ lọc</button><a class="clear-filter" href="<?=sr_url('home')?>#jobs">Xóa bộ lọc</a></form></aside>
<div class="results-column"><div class="results-bar"><div><strong><?=number_format($total,0,',','.')?> việc làm phù hợp</strong><small>Trang <?=$pg?> / <?=$maxPg?></small></div><form method="get" class="sort-form"><input type="hidden" name="page" value="home"><?php foreach(['q'=>$q,'loc'=>$loc,'type'=>$type,'mode'=>$mode,'level'=>$level] as $k=>$v):?><input type="hidden" name="<?=h($k)?>" value="<?=h($v)?>"><?php endforeach;?><label for="job-sort">Sắp xếp</label><select name="sort" id="job-sort" data-autosubmit><option value="newest" <?=$sort==='newest'?'selected':''?>>Mới nhất</option><option value="oldest" <?=$sort==='oldest'?'selected':''?>>Cũ nhất</option><option value="az" <?=$sort==='az'?'selected':''?>>Tên A–Z</option></select><noscript><button type="submit" class="button secondary sm">Áp dụng</button></noscript></form></div>
<?php if(!$jobs):?><div class="panel empty-state"><div class="empty-icon">⌕</div><h3>Chưa tìm thấy việc phù hợp</h3><p>Hãy thay đổi từ khóa hoặc bỏ bớt bộ lọc để xem nhiều cơ hội hơn.</p><a class="button secondary" href="<?=sr_url('home')?>#jobs">Xem tất cả công việc</a></div><?php else:?><div class="job-grid"><?php foreach($jobs as $j)sr_job_card($j,isset($savedIds[(int)$j['id']]));?></div><?php if($maxPg>1):?><nav class="pagination" aria-label="Phân trang việc làm"><?php for($i=1;$i<=$maxPg;$i++):?><a class="<?=$i===$pg?'current':''?>" <?=$i===$pg?'aria-current="page"':''?> href="<?=sr_url('home',['q'=>$q,'loc'=>$loc,'type'=>$type,'mode'=>$mode,'level'=>$level,'sort'=>$sort,'p'=>$i])?>#jobs"><?=$i?></a><?php endfor;?></nav><?php endif;?><?php endif;?></div></div></section>
